        last = -1
        try:
            while True:
                img, fid = SCANNER.preview(last_id=last)
                last = fid
                yield img      # None -> mjpeg waits briefly (no new frame, no error image:
                               # the scanner deliberately yields only on new frames)
        finally:
            log.info("Stream ended: scan-preview")
