# All remaining German: check for any umlauts in string literals/print/docstrings
import re, ast
try:
    tree = ast.parse(content)
    # Get all string literals from the AST
    class StringVisitor(ast.NodeVisitor):
        def __init__(self):
            self.strings = []
        def visit_Constant(self, node):
            if isinstance(node.value, str):
                self.strings.append(node.value)
            self.generic_visit(node)
    v = StringVisitor()
    v.visit(tree)

    german_umlauts = ['ü', 'ö', 'ä', 'ß', 'Ä', 'Ö', 'Ü']
    umlaut_count = 0
    for s in v.strings:
        for uml in german_umlauts:
            if uml in s:
                umlaut_count += 1
                # find location
                line = content[:content.index(s)].count('\n') + 1 if s in content else -1
                if line > 0:
                    print(f'Line ~{line}: Umlaut in: {s[:80]}')
                break
    if umlaut_count == 0:
        print('No German umlauts remain in any string literal - all translations applied.')
except SyntaxError as e:
    print(f'Syntax error: {e}')
