import re
for fname in ['src/chesslab/collect.py', 'src/chesslab/collect_ui.py']:
    lines = open(fname, encoding='utf-8').readlines()
    de_words = ['ungen', 'lich', 'keit', 'heit', 'ung ', 'aufnahme', 'stellung', 'zurück', 'brett', 'figur', 'kamera', 'foto', 'fotos', 'licht', 'reihe', 'rang', 'linie', 'schl']
    for i, line in enumerate(lines, 1):
        ll = line.lower()
        for w in de_words:
            if w in ll:
                # skip false positives
                if w == 'lich' and ('which' in ll or 'publish' in ll or 'establish' in ll or 'english' in ll):
                    continue
                print(f'{fname}:{i}: possible German \"{w}\" -> {line.rstrip()[:100]}')
                break
print('Scan complete.')
"

